const validationErrors = [];

if ($json.route !== 'workspace.persistence.prepared') {
  validationErrors.push('Invalid route: expected workspace.persistence.prepared.');
}
if ($json.status !== 'ready') {
  validationErrors.push('Invalid status: expected ready.');
}

return [{
  json: {
    ...$json,
    validation_errors: validationErrors,
  },
}];

const persistence = $json.persistence && typeof $json.persistence === 'object' && !Array.isArray($json.persistence)
  ? $json.persistence
  : {};
const chapter = $json.chapter && typeof $json.chapter === 'object' && !Array.isArray($json.chapter)
  ? $json.chapter
  : {};

return [{
  json: {
    ...$json,
    chapter_input: {
      workspace_uuid: chapter.workspace_uuid ?? $json.workspace_uuid ?? persistence.workspace_uuid,
      novel_uuid: chapter.novel_uuid ?? $json.novel_uuid ?? persistence.novel_uuid,
      chapter_number: chapter.chapter_number ?? $json.chapter_number,
      chapter_title: chapter.chapter_title ?? $json.chapter_title ?? '',
    },
  },
}];

const input = $json.chapter_input ?? {};
const normalizedNumber = typeof input.chapter_number === 'string' && input.chapter_number.trim() !== ''
  ? Number(input.chapter_number.trim())
  : input.chapter_number;
const titleTypeValid = input.chapter_title == null || typeof input.chapter_title === 'string';

return [{
  json: {
    ...$json,
    normalized_chapter: {
      workspace_uuid: typeof input.workspace_uuid === 'string' ? input.workspace_uuid.trim() : '',
      novel_uuid: typeof input.novel_uuid === 'string' ? input.novel_uuid.trim() : '',
      chapter_number: normalizedNumber,
      chapter_title: typeof input.chapter_title === 'string'
        ? input.chapter_title.trim().replace(/\s+/gu, ' ')
        : '',
    },
    chapter_title_type_valid: titleTypeValid,
  },
}];

const validationErrors = Array.isArray($json.validation_errors)
  ? [...$json.validation_errors]
  : [];
const chapter = $json.normalized_chapter ?? {};

if (!chapter.workspace_uuid) {
  validationErrors.push('workspace_uuid is required.');
}
if (!chapter.novel_uuid) {
  validationErrors.push('novel_uuid is required.');
}
if (!Number.isInteger(chapter.chapter_number) || chapter.chapter_number < 1) {
  validationErrors.push('chapter_number must be a positive integer.');
}
if ($json.chapter_title_type_valid !== true) {
  validationErrors.push('chapter_title must be a string; an empty string is allowed.');
}

return [{
  json: {
    ...$json,
    is_valid: validationErrors.length === 0,
    validation_errors: validationErrors,
  },
}];

const isValid = $json.is_valid === true;
const output = {
  route: 'chapter.create.intake',
  status: isValid ? 'ready' : 'invalid',
  is_valid: isValid,
  validation_errors: $json.validation_errors ?? [],
};

if (isValid) {
  output.target = 'WF-004-P02';
  output.context = {
    workspace_uuid: $json.normalized_chapter.workspace_uuid,
    novel_uuid: $json.normalized_chapter.novel_uuid,
    chapter_number: $json.normalized_chapter.chapter_number,
    chapter_title: $json.normalized_chapter.chapter_title,
    created_at: new Date().toISOString(),
  };
}

return [{ json: output }];
